     "svg": "<svg viewBox=\"0 0 600 260\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect width=\"600\" height=\"260\" fill=\"#fffbeb\"/>\n<rect x=\"190\" y=\"15\" width=\"220\" height=\"50\" rx=\"10\" fill=\"#f59e0b\"/>\n<text x=\"300\" y=\"46\" font-size=\"16\" fill=\"#fff\" font-weight=\"bold\" text-anchor=\"middle\">Происходит всегда?</text>\n<line x1=\"230\" y1=\"65\" x2=\"110\" y2=\"115\" stroke=\"#92400e\" stroke-width=\"3\"/>\n<line x1=\"370\" y1=\"65\" x2=\"420\" y2=\"115\" stroke=\"#92400e\" stroke-width=\"3\"/>\n<text x=\"150\" y=\"90\" font-size=\"15\" fill=\"#166534\" font-weight=\"bold\">ДА</text>\n<text x=\"410\" y=\"90\" font-size=\"15\" fill=\"#b91c1c\" font-weight=\"bold\">НЕТ</text>\n<rect x=\"30\" y=\"115\" width=\"160\" height=\"50\" rx=\"10\" fill=\"#22c55e\"/>\n<text x=\"110\" y=\"146\" font-size=\"16\" fill=\"#fff\" font-weight=\"bold\" text-anchor=\"middle\">ZERO</text>\n<rect x=\"320\" y=\"115\" width=\"200\" height=\"50\" rx=\"10\" fill=\"#f59e0b\"/>\n<text x=\"420\" y=\"146\" font-size=\"16\" fill=\"#fff\" font-weight=\"bold\" text-anchor=\"middle\">Может случиться?</text>\n<line x1=\"360\" y1=\"165\" x2=\"290\" y2=\"200\" stroke=\"#92400e\" stroke-width=\"3\"/>\n<line x1=\"480\" y1=\"165\" x2=\"520\" y2=\"200\" stroke=\"#92400e\" stroke-width=\"3\"/>\n<text x=\"305\" y=\"185\" font-size=\"15\" fill=\"#166534\" font-weight=\"bold\">ДА</text>\n<text x=\"510\" y=\"185\" font-size=\"15\" fill=\"#b91c1c\" font-weight=\"bold\">НЕТ</text>\n<rect x=\"210\" y=\"200\" width=\"160\" height=\"50\" rx=\"10\" fill=\"#3b82f6\"/>\n<text x=\"290\" y=\"231\" font-size=\"16\" fill=\"#fff\" font-weight=\"bold\" text-anchor=\"middle\">FIRST (will)</text>\n<rect x=\"420\" y=\"200\" width=\"170\" height=\"50\" rx=\"10\" fill=\"#a21caf\"/>\n<text x=\"505\" y=\"231\" font-size=\"16\" fill=\"#fff\" font-weight=\"bold\" text-anchor=\"middle\">SECOND (would)</text>\n</svg>"
